using Microsoft.Extensions.DependencyInjection; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Builder; using Microsoft.AspNetCore.Identity; using Microsoft.EntityFrameworkCore; using Microsoft.Extensions.Hosting; using Nimble.Modulith.Users.Data;
namespace Nimble.Modulith.Users;
public static class UsersModuleExtensions
{
 public static IHostApplicationBuilder AddUsersModuleServices(this IHostApplicationBuilder builder, Serilog.ILogger logger){ builder.AddSqlServerDbContext<UsersDbContext>("usersdb"); builder.Services.AddIdentity<IdentityUser,IdentityRole>(o=>{o.Password.RequireDigit=false;o.Password.RequiredLength=6;o.Password.RequireUppercase=false;o.Password.RequireLowercase=false;o.Password.RequireNonAlphanumeric=false;}).AddEntityFrameworkStores<UsersDbContext>().AddDefaultTokenProviders(); builder.Services.AddAuthentication().AddBearerToken(IdentityConstants.BearerScheme); builder.Services.AddAuthorizationBuilder(); logger.Information("Users module services registered"); return builder; }
 public static async Task<WebApplication> EnsureUsersModuleDatabaseAsync(this WebApplication app){ using var s=app.Services.CreateScope(); var db=s.ServiceProvider.GetRequiredService<UsersDbContext>(); await db.Database.EnsureCreatedAsync(); var roleManager=s.ServiceProvider.GetRequiredService<RoleManager<IdentityRole>>(); var userManager=s.ServiceProvider.GetRequiredService<UserManager<IdentityUser>>(); foreach(var r in new[]{"Admin","User"}) if(!await roleManager.RoleExistsAsync(r)) await roleManager.CreateAsync(new IdentityRole(r)); var adminEmail="admin@nimble.local"; var admin=await userManager.FindByEmailAsync(adminEmail); if(admin is null){ admin=new IdentityUser{UserName=adminEmail,Email=adminEmail,EmailConfirmed=true}; await userManager.CreateAsync(admin,"admin123"); await userManager.AddToRoleAsync(admin,"Admin"); } return app; }
}
